import{_ as a,o as l,c as i,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph Orchestrator Meeting 2021-04-20","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2021-04-20","date":"2021-04-20T00:00:00.000Z","updated":"2021-04-21T00:00:00.000Z","tags":["Ceph","分布式存储","管理工具","Ganesha","NVMe over Fabrics"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-04-20.md","filePath":"posts/2021/Ceph_Orchestrator_Meeting_2021-04-20.md","lastUpdated":1780459816000}'),t={name:"posts/2021/Ceph_Orchestrator_Meeting_2021-04-20.md"};function h(o,e,s,n,p,c){return l(),i("div",null,[...e[0]||(e[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h4><p>本次Ceph Orchestrator会议主要围绕Ceph分布式存储系统的部署、管理和优化展开，讨论了多个关键议题，包括Ganesha NFS服务配置、NVMe over Fabrics的实现、密钥管理以及客户端配置管理等。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>Ceph部署与Ganesha NFS服务配置</strong></p><ul><li>讨论了如何优化Ganesha NFS服务的部署，特别是在Ceph环境中。</li><li>决定使用Ceph的调度机制来管理Ganesha服务的重启和故障转移。</li><li>提出了通过Ingress服务和HAProxy来管理NFS服务的IP地址和负载均衡。</li></ul></li><li><p><strong>NVMe over Fabrics的实现</strong></p><ul><li>讨论了在SPDK中实现NVMe over Fabrics的命名空间掩码功能。</li><li>展示了如何在SPDK中通过RPC调用来动态附加和分离控制器到命名空间。</li><li>提出了将SPDK的命名空间掩码功能与Ceph的访问控制机制集成。</li></ul></li><li><p><strong>Ceph部署中的密钥管理</strong></p><ul><li>讨论了在Ceph部署中如何管理密钥环。</li><li>决定在短期内继续使用现有的密钥环部署方式，但未来将修改Ganesha以支持在配置中明确指定密钥。</li></ul></li><li><p><strong>Ceph客户端配置管理</strong></p><ul><li>讨论了如何管理Ceph客户端的配置文件（ceph.conf）。</li><li>提出了通过Ceph的管理工具来动态更新客户端节点的配置文件。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>使用Ceph的调度机制来管理Ganesha NFS服务的重启和故障转移。</li><li>通过Ingress服务和HAProxy来管理NFS服务的IP地址和负载均衡。</li><li>在短期内继续使用现有的密钥环部署方式，未来将修改Ganesha以支持在配置中明确指定密钥。</li><li>通过Ceph的管理工具动态更新客户端节点的配置文件。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>继续优化Ganesha NFS服务的部署和管理。</li><li>在SPDK中实现并测试NVMe over Fabrics的命名空间掩码功能。</li><li>修改Ganesha以支持在配置中明确指定密钥。</li><li>开发Ceph管理工具，动态更新客户端节点的配置文件。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li>需要进一步讨论和测试HAProxy的配置。</li><li>需要与Ganesha开发团队讨论，确保Ganesha服务的配置和管理符合Ceph的最佳实践。</li></ul><h4 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h4><p>本次会议针对Ceph分布式存储系统的多个关键议题进行了深入的讨论，并制定了具体的行动计划，旨在优化Ceph的部署、管理和性能。</p>',13)])])}const _=a(t,[["render",h]]);export{u as __pageData,_ as default};
